// Package cli parses ddkstat arguments and dispatches to the reports.
package cli

import (
	"flag"
	"fmt"
	"io"
)

// Exit codes returned by Run.
const (
	exitOK    = 0
	exitUsage = 2
)

// Run parses args, writes diagnostics to stderr, and returns the process exit code.
// Standard output carries only report output; no report is implemented in this foundation step,
// so every invocation that reaches dispatch is a usage error.
func Run(args []string, stdout, stderr io.Writer) int {
	fs := flag.NewFlagSet("ddkstat", flag.ContinueOnError)
	fs.SetOutput(stderr)
	if err := fs.Parse(args); err != nil {
		return exitUsage
	}
	if fs.NArg() == 0 {
		fmt.Fprintln(stderr, "usage: ddkstat <report> <log.jsonl>")
		return exitUsage
	}
	fmt.Fprintf(stderr, "error: report %q is not implemented\n", fs.Arg(0))
	return exitUsage
}

